#pragma once
#include "external_research_batch.hpp"
#include <functional>
#include <limits>

namespace decisionPacket {
using externalResearchBatch::need;
inline QString text(QJsonValue v,int max=2000){return externalResearchBatch::trim(v.toString()).left(max);}
inline QString code(QJsonValue v){auto s=v.isDouble()?legacyResearchJson::number(v.toDouble()):v.toString();s.remove(QRegularExpression("[^0-9]"));return s.size()<=6?s.rightJustified(6,'0'):QString();}
inline QJsonArray head(QJsonArray a,int n){while(a.size()>n)a.removeLast();return a;}
inline double round2(double x){return QString::number(x,'f',2).toDouble();}
inline QJsonArray latest(QJsonArray entries,QString dataset){QJsonArray valid,out;for(auto v:entries){auto e=v.toObject(),r=e["result"].toObject();if(e["valid"]==true&&!r.isEmpty()&&r["dataManifest"].isObject())valid.append(e);}if(dataset.isEmpty()&&!valid.isEmpty())dataset=valid[0].toObject()["result"].toObject()["dataManifest"].toObject()["datasetId"].toString();QSet<QString>seen;for(auto v:valid){auto e=v.toObject(),r=e["result"].toObject();auto model=r["modelId"].toString();if(!dataset.isEmpty()&&r["dataManifest"].toObject()["datasetId"]!=dataset||seen.contains(model))continue;seen.insert(model);out.append(e);}return out;}
inline double numeric(QJsonValue v){if(v.isNull())return 0;if(v.isBool())return v.toBool()?1:0;if(v.isDouble())return v.toDouble();if(v.isString()){auto s=externalResearchBatch::trim(v.toString());if(s.isEmpty())return 0;bool ok;auto n=s.toDouble(&ok);return ok?n:std::nan("");}return std::nan("");}
inline void add(QMap<QString,QJsonObject>&map,QJsonObject source,QJsonArray rows){
 auto items=head(rows,30);for(int i=0;i<items.size();++i){auto item=items[i].toObject();auto id=code(item.value("code")),name=text(item["name"].toString().isEmpty()?id:item["name"].toString(),100);if(id.isEmpty()||QRegularExpression("(^|\\*)ST",QRegularExpression::CaseInsensitiveOption).match(name).hasMatch())continue;if(!map.contains(id))map[id]={{"code",id},{"name",name},{"signals",QJsonArray{}},{"profile",QJsonObject{}},{"contexts",QJsonArray{}}};auto signalRows=map[id]["signals"].toArray();auto score=numeric(item.value("score"));signalRows.append(QJsonObject{{"sourceId",source["sourceId"]},{"sourceLabel",source["sourceLabel"]},{"sourceType",source["sourceType"]},{"rank",i+1},{"rankPercentile",round2(items.size()<=1?100:100.0*(items.size()-i)/items.size())},{"rawScore",std::isfinite(score)?QJsonValue(score):QJsonValue(QJsonValue::Null)},{"asOf",source["asOf"].toString()},{"datasetId",source["datasetId"].toString()},{"validationStatus",source["validationStatus"].toString().isEmpty()?"context":source["validationStatus"].toString()},{"trainedThrough",item["modelTrainedThrough"].toString().isEmpty()?item["trainedThrough"].toString():item["modelTrainedThrough"].toString()}});auto row=map[id];row["signals"]=signalRows;map[id]=row;}
}
inline double consensus(QJsonArray signalRows){if(signalRows.isEmpty())return 0;double sum=0;QSet<QString>sources;for(auto v:signalRows){auto s=v.toObject();sum+=s["rankPercentile"].toDouble();sources.insert(s["sourceId"].toString());}return round2(sum/signalRows.size()*.7+std::min(sources.size(),qsizetype(3))/3.0*30);}
inline QString prompt(QJsonObject packet){
 QJsonObject content;for(auto k:{"generatedAt","dataSources","candidates","portfolioContext","dataGaps","evidence"})content[k]=packet[k];
 return QStringLiteral("你是一名负责复核的 A 股研究主管。请审查下面的 WebStock 决策包，完成一次量化、产业证据、反方观点和组合风险合并分析。\n\n工作规则：\n- 模型原始分数不能跨模型直接比较，只能使用每个来源内的排名和来源数。\n- “探索性”结果不能写成已验证策略；数据缺口必须保留。\n- 每条外部事实必须引用提供的 evidenceId；没有证据时写“待补证”，不能补写来源不明的事实。\n- 主动寻找模型排序分歧、资讯与专家观点冲突、集中暴露和失效条件。\n- 不调用券商、不输出自动下单指令。价格或盘口缺失时不得虚构。\n\n研究问题：")+packet["question"].toString()+"\n风险偏好："+packet["riskProfile"].toString()+"\n\n决策包 JSON：\n"+researchRuns::pretty(content)+QStringLiteral("\n请输出：\n## 研究结论\n明确最值得继续研究、等待确认和暂时排除的候选。\n\n## 四角色复核\n分别给出量化审查、产业与公司证据、反方/冲突、组合与风险四部分结论。\n\n## 候选审查表\n列出代码、名称、来源共识、支持证据、反证、数据缺口、确认条件、失效条件和研究优先级。\n\n## 纸面组合输入\n只给出适合进入纸面组合草稿的候选及理由，不给真实下单指令。\n\n## 下一步补证\n按优先级列出需要补充的财报、公告、资讯、盘口、行业或点时点数据。\n\n## WebStock 一键复制输出要求\n请在回答最后输出一个可直接复制回 WebStock 的结果块。\n要求：不要把边界标记放进代码块；边界标记必须单独占一行；块内使用 Markdown；内容要短、清楚、可复盘。\n\n格式必须严格如下：\nWEBSTOCK_RESULT_START\n# AI 研究决策包复核结果\n- 研究结论：继续研究 / 等待确认 / 暂时排除。\n- 四角色复核：量化、产业证据、反方冲突、组合风险。\n- 候选审查：代码、证据编号、确认条件、失效条件、数据缺口。\n- 纸面组合输入：仅列候选和研究理由，不生成真实订单。\n- 下一步补证：按优先级列出待核验数据。\nWEBSTOCK_RESULT_END");
}
// Context is an explicit, frozen provider snapshot. No provider or network is invoked here.
inline QJsonObject build(QJsonObject input,QJsonObject context,QJsonObject knowledge,QString generatedAt){
 externalResearchBatch::stamp(generatedAt);auto question=text(input["question"],1000);if(question.isEmpty())question="综合当前量化模型、因子、专家资料和资讯，哪些股票值得继续研究？";auto risk=input["riskProfile"].toString();if(!QStringList{"conservative","balanced","aggressive"}.contains(risk))risk="balanced";double max=numeric(input.value("maxCandidates"));if(!std::isfinite(max)||max==0)max=12;int limit=int(std::min(std::max(max,3.),20.));auto dataset=text(input["datasetId"],100);auto quant=latest(head(context["quantEntries"].toArray(),50),dataset);if(dataset.isEmpty()&&!quant.isEmpty())dataset=quant[0].toObject()["result"].toObject()["dataManifest"].toObject()["datasetId"].toString();QJsonObject factor,screener=context["screener"].toObject();for(auto fv:head(context["factorEntries"].toArray(),30)){auto e=fv.toObject(),r=e["result"].toObject();if(e["valid"]==true&&!r.isEmpty()&&(dataset.isEmpty()||r["dataManifest"].toObject()["datasetId"]==dataset)){factor=e;break;}}
 QMap<QString,QJsonObject>map;QJsonArray sources;bool factorSkipped=false;
 for(auto ev:quant){auto r=ev.toObject()["result"].toObject();QJsonObject s{{"sourceId",r["runId"]},{"sourceLabel",r["modelId"]},{"sourceType","quant-model"},{"asOf",r["asOf"]},{"datasetId",r["dataManifest"].toObject()["datasetId"]},{"validationStatus",r["validationStatus"]},{"metrics",r["metrics"]}};sources.append(s);add(map,s,r["candidates"].toArray());}
 if(!factor.isEmpty()){auto r=factor["result"].toObject(),composite=r["composite"].toObject();QJsonObject admissions;bool eligible=false;for(auto f:r["factors"].toArray()){auto a=f.toObject()["admission"].toString();admissions[a]=admissions[a].toInt()+1;eligible|=a=="candidate";}QJsonObject s{{"sourceId",r["runId"]},{"sourceLabel","验证期加权复合因子"},{"sourceType","factor-lab"},{"asOf",r["asOf"]},{"datasetId",r["dataManifest"].toObject()["datasetId"]},{"validationStatus",r["validationStatus"]},{"metrics",composite["metrics"]},{"rankingEligible",eligible},{"factorAdmissions",admissions}};sources.append(s);if(eligible)add(map,s,composite["candidates"].toArray());else factorSkipped=true;}
 if(!screener.isEmpty()&&screener["result"].isObject()){auto r=screener["result"].toObject();QString label=screener["taskName"].toString();if(label.isEmpty())label=r["strategy"].toString();if(label.isEmpty())label="本地筛选";auto sid=screener["id"].isDouble()?legacyResearchJson::number(screener["id"].toDouble()):screener["id"].toString();QJsonObject s{{"sourceId","screener-"+sid},{"sourceLabel",label},{"sourceType","local-screener"},{"asOf",r["createdAt"].toString().isEmpty()?screener["createdAt"].toString():r["createdAt"].toString()},{"validationStatus","context"},{"strategy",r["strategy"].toString().isEmpty()?screener["strategy"]:r["strategy"]}};sources.append(s);add(map,s,r["candidates"].toArray());}
 auto positions=context["positions"].toArray(),watchlist=context["watchlist"].toArray();QSet<QString>positionCodes,watchCodes;for(auto v:positions)positionCodes.insert(v.toObject()["code"].toString());for(auto v:watchlist)watchCodes.insert(v.toObject()["code"].toString());if(map.isEmpty()){auto rows=positions;for(auto v:watchlist)rows.append(v);add(map,{{"sourceId","portfolio-context"},{"sourceLabel","持仓与自选上下文"},{"sourceType","portfolio-context"},{"validationStatus","context"}},rows);}
 QMap<QString,QJsonObject>profiles;for(auto v:context["profiles"].toArray())profiles[code(v.toObject()["code"])]=v.toObject();QList<QJsonObject>ranked;
 for(auto item:map){auto id=item["code"].toString();auto p=profiles.value(id);auto signalRows=item["signals"].toArray();QSet<QString>seen;double lo=100,hi=0;for(auto v:signalRows){auto s=v.toObject();seen.insert(s["sourceId"].toString());lo=std::min(lo,s["rankPercentile"].toDouble());hi=std::max(hi,s["rankPercentile"].toDouble());}item["consensusScore"]=consensus(signalRows);item["signalCount"]=seen.size();item["modelDisagreement"]=signalRows.size()>1?round2(hi-lo):0;item["industry"]=p["industry"].toString();item["themes"]=head(p[p["themes"].isArray()?"themes":"tags"].toArray(),12);item["boards"]=head(p["boards"].toArray(),8);item["businessSummary"]=p["businessSummary"].toString().isEmpty()?p["businessScope"].toString():p["businessSummary"].toString();item["inPortfolio"]=positionCodes.contains(id);item["inWatchlist"]=watchCodes.contains(id);ranked.append(item);}
 std::sort(ranked.begin(),ranked.end(),[](QJsonObject a,QJsonObject b){if(a["consensusScore"]!=b["consensusScore"])return a["consensusScore"].toDouble()>b["consensusScore"].toDouble();if(a["signalCount"]!=b["signalCount"])return a["signalCount"].toInt()>b["signalCount"].toInt();return a["code"].toString()<b["code"].toString();});QJsonArray candidates;for(int i=0;i<std::min(limit,int(ranked.size()));++i)candidates.append(ranked[i]);
 QStringList tokens{question};for(auto v:candidates){auto c=v.toObject();tokens<<c["code"].toString()<<c["name"].toString();for(auto t:c["themes"].toArray())tokens<<t.toString();tokens<<c["industry"].toString();}QStringList cleaned;for(auto t:tokens){auto s=text(t,80).toLower();if(s.size()>=2)cleaned<<s;}QJsonArray newsEvidence;auto news=context["news"].toObject();for(auto nv:news["items"].toArray()){auto n=nv.toObject();if(n["source"].toString().compare("WebStock Fallback",Qt::CaseInsensitive)==0)continue;QStringList parts{n["title"].toString(),n["summary"].toString(),n["source"].toString()};for(auto a:{"relatedStocks","relatedSectors"})for(auto t:n[a].toArray())parts<<t.toString();auto hay=parts.join(' ').toLower();bool match=false;for(auto t:cleaned)match|=hay.contains(t);if(!match)continue;auto key=n["title"].toString()+"|"+n["link"].toString()+"|"+n["time"].toString();newsEvidence.append(QJsonObject{{"evidenceId","NEWS-"+externalResearchBatch::sha(key).left(12).toUpper()},{"evidenceType","news"},{"title",n["title"]},{"source",n["source"]},{"publishedAt",n["time"]},{"sourceUrl",n["link"]=="#"?QJsonValue(""):n["link"]},{"content",n["summary"].toString().isEmpty()?n["title"]:n["summary"]},{"relatedStocks",n["relatedStocks"].isArray()?n["relatedStocks"]:QJsonValue(QJsonArray{})},{"relatedSectors",n["relatedSectors"].isArray()?n["relatedSectors"]:QJsonValue(QJsonArray{})}});if(newsEvidence.size()==12)break;}
 QJsonArray evidence;for(auto kv:knowledge["items"].toArray()){auto k=kv.toObject();if(!k.contains("evidenceType"))k["evidenceType"]="knowledge";evidence.append(k);}int knowledgeCount=evidence.size();for(auto v:newsEvidence)evidence.append(v);evidence=head(evidence,24);
 QJsonArray gaps;QSet<QString>datasets;for(auto sv:sources){auto d=sv.toObject()["datasetId"].toString();if(!d.isEmpty())datasets.insert(d);}if(datasets.size()>1)gaps.append("候选来源使用了不同数据集，只能作为并列证据，不能做严格模型优劣比较");if(quant.isEmpty())gaps.append("没有可用的量化模型结果");if(factor.isEmpty())gaps.append("没有同数据集因子体检结果");else if(factorSkipped)gaps.append("因子体检没有因子通过“候选”门禁，复合排名未计入共识分");if(screener.isEmpty())gaps.append("没有已保存的本地筛选任务");auto error=text(knowledge["error"],500);if(!error.isEmpty())gaps.append("专家资料库检索失败："+error);else if(!knowledgeCount)gaps.append("专家资料库没有匹配证据");if(newsEvidence.isEmpty())gaps.append("没有匹配且带来源的资讯证据；本地兜底提示未作为外部证据");for(auto c:candidates)if(c.toObject()["businessSummary"].toString().isEmpty()){gaps.append("部分候选缺少主营业务摘要或营收结构");break;}
 QJsonArray ps,ws;for(auto v:positions){auto r=v.toObject();QJsonObject c;for(auto k:{"code","name","quantity","costPrice","finalPnlRate"})if(r.contains(k))c[k]=r[k];ps.append(c);}for(auto v:head(watchlist,50)){auto r=v.toObject();QJsonObject c;for(auto k:{"code","name","groupName"})if(r.contains(k))c[k]=r[k];ws.append(c);}
 QJsonObject packet{{"schema","webstock.research.decision-packet.v1"},{"generatedAt",generatedAt},{"question",question},{"riskProfile",risk},{"datasetId",dataset},{"dataSources",sources},{"candidates",candidates},{"evidence",evidence},{"evidenceEngine",knowledge["engine"].toString("none")},{"newsMeta",news["meta"].toObject()},{"portfolioContext",QJsonObject{{"positions",ps},{"watchlist",ws}}},{"dataGaps",gaps}};packet["prompt"]=prompt(packet);return packet;
}
}
